function newPivot(sheetName){const n=X.pivots.length+1,name="PivotTable"+n,sh=sheetName||("Sheet"+(X.sheets.length+1-(X.sheets.includes("Dashboard")?1:0)));if(!X.sheets.includes(sh))X.sheets.splice(X.sheets.includes("Dashboard")?X.sheets.indexOf("Dashboard"):X.sheets.length,0,sh);
 const p={id:nid("pv"),kind:"pivot",name,sheet:sh,rows:[],cols:[],vals:[],filters:[],cache:X.data.map(r=>Object.assign({},r)),ver:X.ver,group:["years","months"],sort:null,grand:true,subtotals:true};X.pivots.push(p);X.sheet=sh;X.sel=p.id;X.fieldList=true;return p}
function addField(p,f,area){["rows","cols"].forEach(a=>p[a]=p[a].filter(x=>x!==f));p.filters=p.filters.filter(x=>x.f!==f);if(area==="vals"){if(!p.vals.some(v=>v.f===f))p.vals.push({f,agg:NUM.has(f)?"sum":"count",showAs:"none"})}else{p.vals=p.vals.filter(v=>area==="remove"?v.f!==f:true);if(area==="rows")p.rows.push(f);else if(area==="cols")p.cols=[f];else if(area==="filters")p.filters.push({f,sel:null})}if(area==="remove")p.vals=p.vals.filter(v=>v.f!==f)}
function insertChart(type,src){const sh=X.sheet;const ch={id:nid("ch"),kind:"chart",sheet:sh,type,src,title:src.pivot?"Total":"Chart Title",titleOn:!src.pivot||true,labels:false,legend:src.pivot?"right":"bottom",grid:true,switched:false,colors:"color"};if(src.hist){ch.title="Histogram of "+src.hist}X.charts.push(ch);X.sel=ch.id;X.tab="Chart Design";return ch}
function flash(t){X.flash=t;render();clearTimeout(flash.t);flash.t=setTimeout(()=>{X.flash="";const f=$(".xl-flash",root);if(f)f.remove()},4200)}
function setup(kind){if(kind==="pivotBasic"&&!X.pivots.length){const p=newPivot();addField(p,"Category","rows");addField(p,"Sales","vals");flash("Set up: PivotTable1 with Category in Rows and Sum of Sales.")}
 if(kind==="dashPrep"){if(!X.pivots.length){const p=newPivot();addField(p,"Category","rows");addField(p,"Sales","vals")}if(X.pivots.length<2){const p=newPivot();addField(p,"OrderDate","rows");addField(p,"Sales","vals")}
  X.pivots.forEach(p=>{if(!X.charts.some(c=>c.src.pivot===p.id)){X.sheet=p.sheet;const c=insertChart(p.rows.includes("OrderDate")?"line":"column",{pivot:p.id});c.legend="none"}});
  if(!X.slicers.some(s=>s.f==="Region"))X.slicers.push({id:nid("sl"),kind:"slicer",f:"Region",sheet:X.pivots[0].sheet,sel:null,conns:X.pivots.map(p=>p.id),multi:false});
  X.sheet=X.pivots[0].sheet;X.sel=null;flash("Set up: two PivotTables, a PivotChart for each, and a Region slicer connected to both.")}}
function doAct(a,arg){const o=selObj(),p=selPivot();
 switch(a){
  case"ins-pivot":if(X.sheet!=="Data"){flash("Go to the Data sheet first: a PivotTable needs a cell inside the data selected.");return}X.dlg={k:"pivot"};break;
  case"ins-line":case"ins-col":case"ins-colstack":case"ins-col100":case"ins-bar":case"ins-linem":case"ins-area":case"ins-pie":case"ins-donut":case"ins-combo":case"ins-scatter":{const t=a.slice(4);
   if(X.sheet==="Summary"){if(t==="scatter"){flash("A scatter needs two numeric columns per row: try it on the Data sheet with Discount and Profit selected (not in this practice copy). Pick another type here.");return}insertChart(t,{summary:true});break}
   if(p){if(t==="scatter"){flash("PivotCharts can't be scatter, bubble or stock charts in Excel. Choose another type.");return}insertChart(t,{pivot:p.id});break}
   flash(X.sheet==="Data"?"Charts from 364 raw rows aren't useful. Use the Summary sheet, a PivotTable, or select the Sales column for a histogram.":"Select a PivotTable, or go to the Summary sheet, first.");return}
  case"ins-hist":if(X.sheet!=="Data"||!X.colSel||!NUM.has(X.colSel)){flash("Go to the Data sheet and click a numeric column header (e.g. Sales) first.");return}insertChart("hist",{hist:X.colSel});break;
  case"pv-chart":if(!p){flash("Click inside a PivotTable first.");return}X.dlg={k:"chart",pivot:p.id};break;
  case"ins-slicer":case"pv-slicer":if(!p){flash("Click inside a PivotTable first: a slicer belongs to a PivotTable.");return}X.dlg={k:"slicer",pivot:p.id,pick:[]};break;
  case"ins-timeline":case"pv-timeline":if(!p){flash("Click inside a PivotTable first.");return}{const t={id:nid("tl"),kind:"timeline",f:"OrderDate",sheet:X.sheet,level:"months",range:null,conns:[p.id]};X.timelines.push(t);X.sel=t.id;X.tab="Timeline"}break;
  case"pv-group":if(!p||!p.rows.includes("OrderDate")){flash("Put OrderDate in Rows, then select the PivotTable.");return}X.dlg={k:"group",pivot:p.id,pick:p.group.slice()};break;
  case"pv-fields":X.fieldList=!X.fieldList;break;
  case"pv-refresh":case"refresh":X.pivots.forEach(q=>{q.cache=X.data.map(r=>Object.assign({},r));q.ver=X.ver});flash(X.edited?"Refreshed: every PivotTable now shows the edited data.":"Refreshed.");return;
  case"sort-desc":case"sort-asc":if(!p){flash("Select a PivotTable (click inside it) first.");return}p.sort=a==="sort-desc"?"desc":"asc";break;
  case"pv-grand":if(p)p.grand=!p.grand;break;case"pv-subs":if(p)p.subtotals=!p.subtotals;break;
  case"pv-conn":if(!p)return;{const s=X.slicers.concat(X.timelines);if(!s.length){flash("No slicers or timelines yet.");return}X.dlg={k:"conn",target:"pivot",pivot:p.id}}break;
  case"ce-title":if(o&&o.kind==="chart"){if(!o.titleOn||!o.title||o.title==="Chart Title"){o.titleOn=true;X.dlg={k:"title",chart:o.id}}else o.titleOn=false}break;
  case"ce-labels":if(o&&o.kind==="chart")o.labels=!o.labels;break;case"ce-grid":if(o&&o.kind==="chart")o.grid=!o.grid;break;
  case"ce-legend":if(o&&o.kind==="chart")o.legend=arg;break;
  case"cd-switch":if(o&&o.kind==="chart"){if(o.src.hist){flash("A histogram has one series: nothing to switch.");return}o.switched=!o.switched}break;
  case"cd-type":if(o&&o.kind==="chart"){if(o.src.hist){flash("Histogram bins come from the data; change the bin width instead.");return}X.dlg={k:"ctype",chart:o.id}}break;
  case"cd-colors":if(o&&o.kind==="chart")o.colors=o.colors==="mono"?"color":"mono";break;
  case"cd-move":if(o&&o.kind==="chart"){X.dlg={k:"move",obj:o.id}}break;
  case"sl-conn":if(o&&(o.kind==="slicer"||o.kind==="timeline"))X.dlg={k:"conn",target:"slicer",obj:o.id};break;
  case"sl-move":if(o&&(o.kind==="slicer"||o.kind==="timeline")){if(!X.sheets.includes("Dashboard")){flash("Add the Dashboard sheet first (⊕ next to the tabs).");return}o.sheet="Dashboard";X.sheet="Dashboard"}break;
  case"sl-multi":if(o&&o.kind==="slicer")o.multi=!o.multi;break;
  case"tl-level":if(o&&o.kind==="timeline"){o.level=arg;o.range=null}break;
  case"add-sheet":if(!X.sheets.includes("Dashboard")){X.sheets.push("Dashboard");X.sheet="Dashboard";X.sel=null;flash("Added a sheet and renamed it Dashboard.")}else flash("This practice copy has one Dashboard sheet.");break;
  case"ins-kpi":if(!X.pivots.length){flash("Make a PivotTable first.");return}if(X.sheet!=="Dashboard"){flash("Go to the Dashboard sheet first.");return}X.dlg={k:"kpi",pick:X.pivots[0].id};break;
  case"view-grid":X.grid[X.sheet]=!X.grid[X.sheet];break;
  case"fmt-table":if(X.sheet==="Data"){X.table=!X.table;flash(X.table?"Formatted as a Table (SalesData). New rows will be picked up on Refresh.":"Converted back to a normal range.")}else flash("Go to the Data sheet.");return;
  case"delete":if(o){["charts","slicers","timelines","kpis"].forEach(k=>X[k]=X[k].filter(x=>x.id!==o.id));if(o.kind==="pivot"){X.pivots=X.pivots.filter(x=>x.id!==o.id);X.charts=X.charts.filter(c=>c.src.pivot!==o.id);X.slicers.forEach(s=>s.conns=s.conns.filter(i=>i!==o.id))}X.sel=null}break}
 render()}

