function dataGrid(){const cols=["#",...COLS],L=i=>i<26?String.fromCharCode(65+i):"A"+String.fromCharCode(39+i);
 return`<div class="xg${X.grid.Data===false?" nogrid":""}${X.table?" tbl-fmt":""}"><table><thead><tr><th class="rn"></th>${COLS.map((c,i)=>`<th class="cl${X.colSel===c?" sel":""}" data-col="${c}">${L(i)}</th>`).join("")}</tr><tr><th class="rn">1</th>${COLS.map(c=>`<th class="hd${X.colSel===c?" sel":""}" data-col="${c}">${c}</th>`).join("")}</tr></thead><tbody>${X.data.map((r,i)=>`<tr><th class="rn">${i+2}</th>${COLS.map(c=>`<td class="${NUM.has(c)?"n":""}${X.colSel===c?" sel":""}" ${c==="Sales"?`data-edit="${i}"`:""}>${esc(c==="Discount"?r[c]:fmt2(r[c]))}</td>`).join("")}</tr>`).join("")}</tbody></table></div>`}
